const wf = $json.workflow || {};
const exec = $json.execution || {};
const trigger = $json.trigger || {};
return [{
  json: {
    workflow: wf.name || 'Sports Betting Prediction Orchestrator',
    node: (exec.lastNodeExecuted) || (trigger.name) || 'unknown',
    message: (exec.error && exec.error.message) || 'Unknown error',
    time: new Date().toISOString()
  }
}];
